<script setup>
import {computed,nextTick,onUnmounted,ref,watch} from 'vue'
import {api} from '../lib'
import Icon from './Icon.vue'
import {parseNamingTemplate,serializeNamingTemplate,reorderRuleItems} from '../naming-template'
import {useRuleReorder} from '../useRuleReorder'
const props=defineProps({modelValue:{type:Object,required:true},catalog:{type:Object,required:true},disabled:Boolean})
const emit=defineEmits(['update:modelValue','validity'])
const tab=ref('tv'),mode=ref('visual'),selected=ref(-1),editing=ref(-1),text=ref('.'),textError=ref(''),preview=ref(null),previewError=ref(''),previewLoading=ref(false)
const label=computed(()=>tab.value==='tv'?'剧集':'电影'),source=computed(()=>props.modelValue[tab.value]||''),parsed=computed(()=>parseNamingTemplate(source.value,props.catalog.variables,tab.value)),tokens=computed(()=>parsed.value.tokens)
const groups=computed(()=>[...new Set(props.catalog.variables.filter(v=>!v.tvOnly||tab.value==='tv').map(v=>v.group))])
const variable=id=>props.catalog.variables.find(v=>v.id===id)
const used=computed(()=>{const last=tokens.value.map(t=>t.kind).lastIndexOf('path');return new Set(tokens.value.slice(last+1).filter(t=>t.kind==='variable').map(t=>t.value))})
const canText=computed(()=>tokens.value.slice(tokens.value.map(t=>t.kind).lastIndexOf('path')+1).some(t=>t.kind==='variable'))
function patch(value){emit('update:modelValue',{...props.modelValue,[tab.value]:value})}
function setTokens(value){patch(serializeNamingTemplate(value));editing.value=-1}
function add(kind,value){setTokens([...tokens.value,{kind,value}]);selected.value=tokens.value.length}
function move(from,to){if(props.disabled||Number(to)<0||Number(to)>=tokens.value.length)return;setTokens(reorderRuleItems(tokens.value,Number(from),Number(to)));selected.value=Number(to)}
const drag=useRuleReorder('.naming-token',move,()=>props.disabled||mode.value!=='visual')
function remove(){const list=[...tokens.value];list.splice(selected.value,1);setTokens(list);selected.value=-1}
async function edit(index){if(props.disabled||tokens.value[index]?.kind!=='text')return;editing.value=index;selected.value=index;text.value=tokens.value[index].value===' '?'':tokens.value[index].value;textError.value='';await nextTick();document.querySelector('.naming-text-editor input')?.focus()}
function applyText(){if(/[\/\\{}<>:"|?*\x00-\x1f\x7f]/.test(text.value)){textError.value='文本不能含路径符号、花括号、控制字符或文件名禁用字符';return}const list=[...tokens.value];list[editing.value]={kind:'text',value:text.value||' '};setTokens(list)}
let timer,ticket=0,alive=true
watch(()=>[props.modelValue,props.catalog],()=>{emit('validity',['tv','movie'].every(k=>!parseNamingTemplate(props.modelValue[k],props.catalog.variables,k).error))},{deep:true,immediate:true})
watch(tab,()=>{selected.value=-1;editing.value=-1;drag.cancel()})
watch(()=>[source.value,tab.value],()=>{clearTimeout(timer);const run=++ticket;preview.value=null;previewError.value='';previewLoading.value=tab.value!=='multi';if(tab.value==='multi')return;timer=setTimeout(async()=>{try{const result=await api('/naming-rules/preview','POST',{source:source.value,mediaType:tab.value});if(alive&&run===ticket)preview.value=result}catch(e){if(alive&&run===ticket)previewError.value=e.message}finally{if(alive&&run===ticket)previewLoading.value=false}},200)},{immediate:true})
onUnmounted(()=>{alive=false;ticket++;clearTimeout(timer)})
async function tabKey(event){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)||props.disabled)return;event.preventDefault();const root=event.currentTarget,order=['tv','movie','multi'];tab.value=event.key==='Home'?'tv':event.key==='End'?'multi':order[(order.indexOf(tab.value)+(event.key==='ArrowRight'?1:2))%3];await nextTick();root.querySelector('[aria-selected=true]')?.focus()}
</script>
<template>
 <section class="naming-rule-editor" aria-label="命名模板配置">
  <div role="tablist" aria-label="命名编辑栏目" class="rule-editor-tabs" @keydown="tabKey"><button v-for="item in [{id:'tv',name:'剧集命名',icon:'Tv'},{id:'movie',name:'电影命名',icon:'Film'},{id:'multi',name:'多版命名',icon:'Layers3'}]" :key="item.id" type="button" role="tab" :aria-selected="tab===item.id" :tabindex="tab===item.id?0:-1" :disabled="disabled" @click="tab=item.id"><Icon :name="item.icon" :size="17"/>{{item.name}}</button></div>
  <div v-if="tab==='multi'" class="rule-editor-placeholder" role="tabpanel" aria-label="多版命名"><Icon name="Layers" :size="28"/><p>多版命名暂未开放</p></div>
  <section v-else role="tabpanel" :aria-label="`${label}命名`">
   <header class="naming-editor-header"><strong>{{label}}目录与文件名称</strong><div class="naming-mode" role="group" aria-label="模板编辑模式"><button type="button" :aria-pressed="mode==='visual'" :disabled="disabled||!!parsed.error" @click="mode='visual'"><Icon name="Eye" :size="16"/>可视化</button><button type="button" :aria-pressed="mode==='source'" :disabled="disabled" @click="mode='source'"><span aria-hidden="true">{ }</span>源码</button></div></header>
   <p class="rule-editor-help">模板结构 · 绿色为变量，米黄为文本，橙色“/”创建下一级目录。变量在每个路径区段内可用一次。</p>
   <textarea v-if="mode==='source'" :value="source" :aria-label="`${label}命名源码`" class="naming-source" spellcheck="false" :disabled="disabled" maxlength="8192" @input="patch($event.target.value)"/>
   <div v-else class="naming-structure" aria-label="模板结构">
    <div v-for="(token,i) in tokens" :key="i" class="naming-token" :class="[token.kind,{selected:selected===i,'sort-target':drag.target.value===String(i),'sort-active':drag.active.value===String(i)}]" :data-sort-id="i">
     <button class="rule-sort-handle" type="button" :aria-label="`拖动标签 ${i+1}`" :disabled="disabled" @pointerdown="drag.begin($event,i)" @keydown.alt.left.prevent="move(i,i-1)" @keydown.alt.right.prevent="move(i,i+1)"><Icon name="GripVertical" :size="15"/></button>
     <button type="button" class="naming-token-label" :aria-label="`选择标签 ${i+1}`" :disabled="disabled" @click="selected=i" @dblclick="edit(i)"><template v-if="token.kind==='variable'">{{variable(token.value)?.label||token.value}} <code>{{'{'+token.value+'}'}}</code></template><template v-else-if="token.kind==='path'">路径 /</template><template v-else>文本 <code>{{token.value.trim()?token.value:'空格'}}</code></template></button>
    </div>
    <p v-if="!tokens.length" class="muted">点击下方变量开始创建模板</p>
   </div>
   <div v-if="mode==='visual'&&selected>=0&&tokens[selected]" class="naming-token-actions" role="group" aria-label="所选标签操作"><span>标签 {{selected+1}}</span><button type="button" class="btn" :disabled="disabled||selected===0" @click="move(selected,selected-1)">前移</button><button type="button" class="btn" :disabled="disabled||selected===tokens.length-1" @click="move(selected,selected+1)">后移</button><button v-if="tokens[selected].kind==='text'" type="button" class="btn" :disabled="disabled" @click="edit(selected)">编辑文本</button><button type="button" class="btn danger-text" :disabled="disabled" @click="remove">移除</button></div>
   <div v-if="editing>=0" class="naming-text-editor"><label>连接符<input v-model="text" aria-label="连接符文本" maxlength="200" :disabled="disabled" @keydown.enter.prevent="applyText" @keydown.esc.stop.prevent="editing=-1"/></label><button type="button" class="btn" :disabled="disabled" @click="applyText">应用文本</button><p v-if="textError" role="alert" class="error-message">{{textError}}</p><small>留空表示空格；仅在首个变量后、后方还有变量时生效。</small></div>
   <p v-if="parsed.error" class="error-message" role="alert">{{parsed.error}}，请在源码中调整。</p>
   <section class="naming-candidates" aria-label="插入变量"><h3>插入变量</h3><div v-for="group in groups" :key="group" class="naming-candidate-row"><strong>{{group}}</strong><div><button v-for="v in catalog.variables.filter(v=>v.group===group&&(!v.tvOnly||tab==='tv'))" :key="v.id" type="button" :disabled="disabled||used.has(v.id)" :aria-label="`插入${v.label}`" @click="add('variable',v.id)">{{v.label}}<code v-if="v.id==='season_episode'"> {season_episode}</code></button></div></div><div class="naming-candidate-row"><strong>辅助标签</strong><div><button type="button" class="text-helper" :disabled="disabled||!canText" @click="add('text','.')">文本标签 .</button><button type="button" class="path-helper" :disabled="disabled||!canText" @click="add('path','/')">路径 /</button></div></div></section>
   <section class="naming-preview" aria-label="命名示例" aria-live="polite"><h3><Icon name="Eye" :size="16"/>示例</h3><p v-if="previewLoading" class="muted">更新示例…</p><p v-else-if="previewError" class="error-message">{{previewError}}</p><template v-else-if="preview"><div><strong>{{label}}目录</strong><span>{{preview.directory||'当前目录'}}</span></div><div><strong>文件名称</strong><span>{{preview.filename}}</span></div></template></section>
   <button type="button" class="btn" :disabled="disabled" @click="emit('update:modelValue',JSON.parse(JSON.stringify(catalog.defaults)))"><Icon name="RotateCcw" :size="16"/>恢复默认命名配置</button>
  </section>
 </section>
</template>
<style scoped>
.naming-rule-editor{min-width:0}.naming-editor-header{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:16px 0}.naming-editor-header strong{font-size:14px}.naming-mode{display:flex;border:1px solid var(--border);border-radius:8px;overflow:hidden}.naming-mode button{display:flex;gap:7px;align-items:center;min-height:40px;border:0;background:var(--layer-item);color:var(--muted);padding:8px 12px;cursor:pointer}.naming-mode button[aria-pressed=true]{color:var(--primary);background:var(--primary-soft)}.naming-mode button+button{border-left:1px solid var(--border)}.naming-structure{display:flex;gap:8px;flex-wrap:wrap;padding:14px;min-height:140px;background:var(--layer-item);border:1px solid var(--border);border-radius:10px;align-content:flex-start}.naming-token{display:flex;align-items:center;min-width:0;max-width:100%;border:1px solid #a4d3bf;border-radius:8px;background:#eaf4ef;color:#315f4c}.naming-token.text{border:1px dashed #ddc69c;background:#faf3e5;color:#816131}.naming-token.path{border-color:#e7b783;background:#fff0de;color:#94531c}.naming-token.selected{box-shadow:0 0 0 2px var(--primary)}.naming-token-label{display:flex;gap:6px;align-items:center;min-width:0;padding:9px 10px 9px 0;border:0;background:none;color:inherit;cursor:pointer;overflow-wrap:anywhere;text-align:left;flex-wrap:wrap;font-size:12px}.naming-token code{overflow-wrap:anywhere;font-size:12px;white-space:pre-wrap}.naming-source{width:100%;min-height:180px!important;font-family:monospace;line-height:1.8;resize:vertical;overflow-wrap:anywhere}.naming-token-actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:12px;font-size:12px}.naming-token-actions .btn{min-height:32px;padding:5px 9px;font-size:12px}.naming-text-editor{display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap;padding:12px;margin-top:12px;background:var(--layer-item);border-radius:8px}.naming-text-editor label{flex:1;min-width:120px;font-size:12px}.naming-text-editor small,.naming-text-editor p{flex-basis:100%}.naming-text-editor input{height:40px}.naming-candidates{margin-top:18px;border:1px solid var(--border);background:var(--layer-item);border-radius:10px;padding:14px}.naming-candidates h3,.naming-preview h3{font-size:14px;margin:0 0 14px}.naming-candidate-row{display:flex;gap:12px;margin-top:12px;align-items:flex-start}.naming-candidate-row>strong{font-size:12px;width:68px;flex:none;padding-top:6px}.naming-candidate-row>div{display:flex;gap:6px;flex-wrap:wrap;min-width:0}.naming-candidate-row button{border:1px solid var(--border);background:var(--surface);border-radius:7px;min-height:32px;padding:5px 8px;color:var(--text);font-size:12px;cursor:pointer}.naming-candidate-row button:disabled{opacity:.38;cursor:default;filter:grayscale(1)}.naming-candidate-row button:hover:enabled{border-color:var(--primary);color:var(--primary)}.naming-candidate-row .text-helper{background:#faf3e5;color:#816131}.naming-candidate-row .path-helper{background:#fff0de;color:#94531c}.naming-preview{margin-top:20px}.naming-preview h3{display:flex;align-items:center;gap:8px}.naming-preview>div{display:flex;gap:14px;padding:12px 0;border-top:1px dashed var(--border);font-size:12px;line-height:1.8}.naming-preview strong{width:60px;flex:none}.naming-preview span{overflow-wrap:anywhere;min-width:0;font-family:monospace}.sort-target{outline:2px dashed var(--primary);outline-offset:2px}.sort-active{opacity:.6}
:global([data-theme=dark] .naming-rule-editor .naming-token){background:#243c33;border-color:#416c59;color:#b9dacb}:global([data-theme=dark] .naming-rule-editor .naming-token.text),:global([data-theme=dark] .naming-rule-editor .text-helper){background:#3c3426;border-color:#7d6846;color:#e4cca1}:global([data-theme=dark] .naming-rule-editor .naming-token.path),:global([data-theme=dark] .naming-rule-editor .path-helper){background:#483324;border-color:#a16c3c;color:#efbf8e}
@media(max-width:480px){.naming-structure,.naming-candidates{padding:10px}.naming-candidate-row{flex-direction:column;gap:5px}.naming-candidate-row>strong{width:auto}.naming-preview>div{gap:8px}}
.naming-token.selected{box-shadow:0 0 0 1px color-mix(in srgb,var(--primary) 55%,transparent)}.naming-token-label:focus-visible{outline:1px solid color-mix(in srgb,var(--primary) 65%,transparent);outline-offset:-2px;border-radius:5px}
</style>
